-- S18 JOIN: Form 4s in the EDGAR table filed more than 21 business days after the trade date (period of report), matched on accession number
-- to the insider-trading tables for who filed and what the trade was (owner, relationship, transaction code, shares, value)
WITH a AS (SELECT column1 acc FROM VALUES ('0000018230-21-000017'),('0000018230-21-000016'),('0001209191-24-001498'),('0001494732-18-000014'),('0001127602-21-003598'),('0001628280-26-001411'),('0001127602-23-002146'),('0001760862-21-000002'),('0000200406-26-000070'),('0001209191-20-032183'),('0001209191-23-045935'),('0001045810-20-000131'),('0001062993-23-013582'),('0001127602-25-012528'),('0001127602-25-012512'),('0001193125-26-193335'),('0001127602-18-023301'),('0000899243-23-020637'),('0001127602-22-011605'),('0001104659-23-011402'),('0001045810-23-000267'),('0001045810-24-000232'),('0001415889-25-003895'),('0001193125-26-054947'),('0000019617-25-001028'),('0001127602-24-022154'),('0001127602-25-012505'),('0001127602-25-012515'),('0001104659-22-116967'),('0001127602-23-022303'),('0000899243-20-018948'),('0001771340-19-000009'),('0000018230-20-000287'),('0001127602-18-023298'),('0001127602-23-005832'),('0001127602-23-002050'),('0001127602-22-002096'),('0001127602-25-012510'),('0001771340-19-000010'),('0001209191-23-050684'),('0001127602-19-019227'),('0001127602-25-012518'),('0001045810-24-000038'),('0001209191-23-012738'),('0001225208-24-009300'),('0001127602-25-012522'),('0001225208-23-001899'),('0001062993-21-002321'),('0001127602-18-000746'),('0001127602-25-012520'),('0001127602-19-027603'),('0001127602-25-012525'),('0001626431-20-000039'),('0001127602-23-002926'),('0001209191-17-065069'),('0001225208-20-002167'),('0001209191-23-053898'),('0000320193-23-000081'),('0001127602-13-031506'),('0000950170-24-088112'),('0001495158-21-000003'),('0000200406-24-000090'),('0001209191-24-003227'),('0001104659-24-024295'),('0001127602-25-012508'),('0000789019-25-000120'),('0001127602-23-000726'),('0001127602-18-023307'),('0001728451-18-000006'),('0001209191-22-037303'),('0001104659-22-019407'),('0001127602-24-019287'),('0001141391-19-000050'),('0000018230-21-000058'))
SELECT a.acc, s.ISSUER_TICKER, s.FILING_DATE, s.PERIOD_OF_REPORT, o.OWNER_NAME, o.RELATIONSHIP, o.TITLE,
  t.TRANSACTION_DATE, t.TRANSACTION_CODE, t.SHARES, t.PRICE_PER_SHARE, t.TRANSACTION_VALUE, t.ACQUIRED_DISPOSED
FROM a
LEFT JOIN LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_SUBMISSION s ON s.ACCESSION_NUMBER = a.acc
LEFT JOIN LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_REPORTINGOWNER o ON o.ACCESSION_NUMBER = a.acc
LEFT JOIN LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_NONDERIV_TRANS t ON t.ACCESSION_NUMBER = a.acc
ORDER BY s.ISSUER_TICKER, a.acc;
